CREATE OR REPLACE FUNCTION public.consume_audit_request(_ip text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN PERFORM pg_advisory_xact_lock(hashtextextended('website-audit:' || _ip, 0)); IF (SELECT count(*) FROM public.rate_limits WHERE ip = 'audit:' || _ip AND created_at > now() - interval '1 minute') >= 5 THEN RETURN false; END IF; INSERT INTO public.rate_limits(ip) VALUES ('audit:' || _ip); DELETE FROM public.rate_limits WHERE ip = 'audit:' || _ip AND created_at < now() - interval '1 hour'; RETURN true; END; $$; REVOKE ALL ON FUNCTION public.consume_audit_request(text) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.consume_audit_request(text) TO service_role;